// shader_registry.h — build-time compiled Slang kernels, embedded as text.
// Generated by cmake/Shaders.cmake (ntscrt_add_shaders) through
// core/gpu/tools/shaderc.cpp; looked up by gpu::Device::kernel().
#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace ntscrt::gpu {

struct ShaderEntry {
    const char *name;       // entry point
    const char *hlsl;       // HLSL text for D3DCompile(name, "cs_5_0")
    uint32_t threads[3];    // [numthreads]
    // Structured buffer element strides (bytes) for t8..t15 then u8..u15;
    // 0 = slot unused.
    uint32_t buffer_strides[16];
    uint32_t cb_size;       // b0 size in bytes, 0 = none
};

struct ShaderFile {
    const char *stem;       // file stem, first half of "<stem>/<entry>"
    const char *msl;        // one Metal library holding every entry point
    const ShaderEntry *entries;
    size_t count;
};

void register_shader_files(const ShaderFile *const *files, size_t n);
// name = "<stem>/<entry>". Returns nullptr if unknown.
const ShaderEntry *find_shader(std::string_view name, const ShaderFile **file_out = nullptr);

struct ShaderRegistrar {
    ShaderRegistrar(const ShaderFile *const *files, size_t n) { register_shader_files(files, n); }
};

}  // namespace ntscrt::gpu
